import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Резервные копии и восстановление","description":"","frontmatter":{"pageId":"admins/backup-recovery","contentRevision":1},"headers":[],"relativePath":"ru/admins/backup-recovery.md","filePath":"ru/admins/backup-recovery.md"}'),i={name:"ru/admins/backup-recovery.md"};function l(s,a,c,d,n,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="резервные-копии-и-восстановление" tabindex="-1">Резервные копии и восстановление <a class="header-anchor" href="#резервные-копии-и-восстановление" aria-label="Permalink to &quot;Резервные копии и восстановление&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Используй согласованную копию БД и сейвов. Онлайн-копия: <code>rimlink-tools backup --data &lt;DataDir&gt; --out &lt;backup.tar.zst&gt;</code>; без --out файл появляется в backups. API POST /api/admin/backups создаёт копию, GET /backups перечисляет, GET /backups/{name} скачивает. Автоматически: Backup:IntervalHours=24, Keep=7 по умолчанию.</p><p>Перед восстановлением останови сервер, сохрани текущий каталог отдельно и проверь выбранную копию в изолированной среде. <code>rimlink-tools restore --data &lt;DataDir&gt; --from &lt;backup.tar.zst&gt;</code> заменяет БД и сейвы. После запуска проверь /health, версии сейвов, вход и доставку незавершённых операций. Не соединяй игроков с тестовой восстановленной копией.</p><p>Откат одного игрока через admin rollback — не полное восстановление сервера. Согласуй его с состоянием эскроу и восстановительными журналами клиента.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не удаляй save-storage.lock: утилита держит его вместе с блокировкой хранилища на время снимка/упаковки. Не предполагается, что любая старая версия существует полным .rws.zst: она может быть delta. Проверяй восстановимость, а не только наличие архива.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./updating">Обновление сервера и клиентов</a></li><li><a href="./../developers/storage">Хранилище и эскроу</a></li><li><a href="./../players/saves-recovery">Сохранения и восстановление</a></li></ul>',10)])])}const h=e(i,[["render",l]]);export{m as __pageData,h as default};
